// Package ui embeds the built web UI for the AgentShield binary.
package ui

import (
	"embed"
	"io/fs"
)

// dist is generated by "make ui"; the tracked .gitkeep keeps this pattern valid before the first build.
//
//go:embed all:dist
var dist embed.FS

// Assets returns the built UI rooted at index.html.
func Assets() fs.FS {
	assets, err := fs.Sub(dist, "dist")
	if err != nil {
		panic(err)
	}
	return assets
}
